using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class DestinationRouteWalk {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit scene required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var plan=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/B5_DestinationColors/plan.json"));var p=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=p.GetComponent<CharacterController>();var pos=p.transform.position;bool enabled=cc.enabled;var results=new List<object>();float radius=cc.radius;try{foreach(var route in plan["routes"]){var points=route["points"].Select(t=>new Vector3((float)t[0],-82,(float)t[1])).ToArray();cc.enabled=false;p.transform.position=points[0]+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();int steps=0;bool okay=true;float remain=0;foreach(var to in points.Skip(1)){for(int n=0;n<45;n++){var d=to-p.transform.position;d.y=0;remain=d.magnitude;if(remain<.035f)break;cc.Move(d.normalized*Mathf.Min(.08f,remain)+Vector3.down*.08f);steps++;}if(remain>.08f){okay=false;break;}}results.Add(new{id=(string)route["id"],steps,remaining=remain,passed=okay});}}finally{cc.enabled=false;p.transform.position=pos;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}var result=new{radius,routes=results};File.WriteAllText(repo+"/Docs/검수/2026-11-08_B5_DestinationColors/route_walk.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
